-- composition of rule kernels DistinctOpt x OrderBySubq (sqlite), template graft_exists
CREATE TABLE t (a,b,c,d);
INSERT INTO t VALUES (1,2,3,4),(2,3,4,5);
WITH cte1 AS MATERIALIZED (SELECT CAST(5e-324 AS REAL) AS c0 ORDER BY 1) SELECT CAST(1 AS INTEGER) AS c0, CAST(1.5 AS NUMERIC) AS c1 FROM (SELECT * FROM cte1 WHERE EXISTS (SELECT 1 FROM (SELECT DISTINCT c FROM t) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT DISTINCT c FROM t) AS kb)) AS a1 GROUP BY a1.c0 UNION SELECT CAST(1 AS INTEGER) AS c0, CAST(42.5 AS NUMERIC) AS c1;
